class RemisePourcentage:
    def __init__(self, taux):
        self.taux = taux

    def appliquer(self, total):
        return total * (1 - self.taux / 100)


class Panier:
    def __init__(self, remise=None):
        self._lignes = {}
        self.remise = remise or SansRemise()

    def ajouter(self, produit, quantite=1):
        ligne = self._lignes.get(produit.reference)
        if ligne:
            ligne.quantite += quantite
        else:
            self._lignes[produit.reference] = Ligne(produit, quantite)

    def __len__(self):
        return sum(ligne.quantite for ligne in self._lignes.values())

    @property
    def total(self):
        brut = sum(ligne.total for ligne in self._lignes.values())
        return round(self.remise.appliquer(brut), 2)


